    _notify_workspace(
        team_id,
        {
            "type": "workspace.owner.transfer",
            "team_id": team_id,
            "user_id": body.user_id,
            "by": user["display_name"],
            "by_user_id": user["id"],
        },
    )
    return {"member": member}


