@app.post("/api/projects/{project_id}/files/{filename:path}/draw-hole")
def draw_hole_file(
    project_id: str,
    filename: str,
    body: DrawHoleRequest,
    user: dict[str, Any] = Depends(get_current_user),
):
    project_path = _require_project(user, project_id)
    src = project_path / filename
    if not src.is_file():
        raise HTTPException(404, "File not found")

    mesh = cad_service.load_mesh(src)
    try:
        if body.placement == "center":
            if body.face_index is None:
                raise ValueError("Pick a face first so Draw can find the face center.")
            position, axis = cad_service.face_region_center_and_normal(mesh, body.face_index)
        else:
            if not body.position:
                raise ValueError("Pick a face or point first so Draw knows where to place the hole.")
            position = body.position
            axis = body.normal or [0, 0, 1]
        diameter = cad_service.length_from_mm(mesh, body.diameter_mm)
        depth = cad_service.length_from_mm(mesh, body.depth_mm) if body.depth_mm is not None else None
        count = int(body.pattern_count or 1)
        if count > 1:
            center = position
            ax = [float(v) for v in (axis or [0, 0, 1])]
            norm = math.sqrt(sum(v * v for v in ax)) or 1.0
            n = [v / norm for v in ax]
            helper = [0.0, 0.0, 1.0] if abs(n[2]) < 0.9 else [1.0, 0.0, 0.0]
            u = [
                n[1] * helper[2] - n[2] * helper[1],
                n[2] * helper[0] - n[0] * helper[2],
                n[0] * helper[1] - n[1] * helper[0],
            ]
            u_norm = math.sqrt(sum(v * v for v in u)) or 1.0
            u = [v / u_norm for v in u]
            v = [
                n[1] * u[2] - n[2] * u[1],
                n[2] * u[0] - n[0] * u[2],
                n[0] * u[1] - n[1] * u[0],
            ]
            radius_mm = body.pattern_radius_mm or max(body.diameter_mm * 2.5, body.diameter_mm + 2.0)
            radius = cad_service.length_from_mm(mesh, radius_mm)
            result = mesh
            for i in range(count):
                t = (math.tau * i) / count
                pt = [
                    center[j] + radius * (math.cos(t) * u[j] + math.sin(t) * v[j])
                    for j in range(3)
                ]
                result = cad_service.hole_at_point(
                    result,
                    pt,
                    axis=axis,
                    diameter=diameter,
                    depth=depth,
                    through=body.through_all,
                )
        else:
            result = cad_service.hole_at_point(
                mesh,
                position,
                axis=axis,
                diameter=diameter,
                depth=depth,
                through=body.through_all,
            )
    except ValueError as exc:
        raise HTTPException(422, str(exc)) from exc

    stem = src.stem.replace("_edited", "").replace("_hole", "") + "_hole"
    out = project_path / f"{stem}.glb"
    cad_service.export_mesh(result, out)
    meta = {
        "face_index": body.face_index,
        "position": position,
        "normal": axis,
        "diameter_mm": body.diameter_mm,
        "depth_mm": body.depth_mm,
        "placement": body.placement,
        "through_all": body.through_all,
        "pattern_count": body.pattern_count,
        "pattern_radius_mm": body.pattern_radius_mm,
    }
    entry = _record_history(
        project_path,
        "hole",
        f"Hole {body.diameter_mm:g}mm",
        out.name,
        meta=meta,
        user=user,
    )
    _append_mesh_edit(project_path, filename, {"op": "draw_hole", "parent": filename, "child": out.name, **meta})
    project_store.touch_project(project_path)
    _notify_project(
        project_id,
        {
            "type": "model.reload",
            "filename": out.name,
            "url": f"/api/projects/{project_id}/files/{out.name}",
            "by": user["display_name"],
            "by_user_id": user["id"],
            "action": "draw_hole",
            "timeline_entry": entry,
        },
    )
    return {
        "filename": out.name,
        "url": f"/api/projects/{project_id}/files/{out.name}",
        "timeline_index": entry["index"],
        "meta": meta,
        "parent": filename,
        "action": "draw_hole",
        "message": (
            f"Added {count} holes, {body.diameter_mm:g} mm diameter"
            if count > 1
            else f"Added a {body.diameter_mm:g} mm {'through-' if body.through_all else 'blind '}hole."
        ),
    }


def _primitive_feature(body: CreatePrimitiveRequest) -> dict[str, Any]:
    op = str(body.op or "").strip().lower()
    if op not in {"box", "cylinder", "sphere", "cone", "torus"}:
        raise ValueError(f"Unsupported primitive '{body.op}'")
    combine = str(body.combine or "new").strip().lower()
    if combine not in {"new", "add", "cut", "intersect"}:
        raise ValueError(f"Unknown combine mode '{body.combine}'")
    feat: dict[str, Any] = {"op": op, "combine": combine, "at": [float(v) for v in body.at[:3]]}
    if op == "box":
        if not all(v and v > 0 for v in (body.length, body.width, body.height)):
            raise ValueError("Box needs positive length, width, and height")
        feat.update(length=float(body.length), width=float(body.width), height=float(body.height))
    elif op == "cylinder":
        if not body.radius or body.radius <= 0 or not body.height or body.height <= 0:
            raise ValueError("Cylinder needs positive radius and height")
        feat.update(radius=float(body.radius), height=float(body.height))
    elif op == "sphere":
        if not body.radius or body.radius <= 0:
            raise ValueError("Sphere needs a positive radius")
        feat.update(radius=float(body.radius))
    elif op == "cone":
        br = body.bottom_radius if body.bottom_radius is not None else body.radius
        if not br or br <= 0 or not body.height or body.height <= 0:
            raise ValueError("Cone needs positive bottom radius and height")
        feat.update(bottom_radius=float(br), top_radius=float(body.top_radius or 0.0), height=float(body.height))
    else:  # torus
        if not body.major_radius or body.major_radius <= 0 or not body.minor_radius or body.minor_radius <= 0:
            raise ValueError("Torus needs positive major and minor radii")
        feat.update(major_radius=float(body.major_radius), minor_radius=float(body.minor_radius))
    return feat


def _next_primitive_basename(project_path: Path, op: str) -> str:
    if not (project_path / f"{op}.glb").is_file():
        return op
    i = 2
    while (project_path / f"{op}{i}.glb").is_file():
        i += 1
    return f"{op}{i}"


@app.post("/api/projects/{project_id}/create-primitive")
def create_primitive(
    project_id: str,
    body: CreatePrimitiveRequest,
    user: dict[str, Any] = Depends(get_current_user),
):
    """Place a parametric primitive via FreeCADCmd — no FeatureProgram / mesh kernel."""
    from backend.services.freecad_engine import create_primitive_solid, freecad_available

    project_path = _require_project(user, project_id)
    try:
        feat = _primitive_feature(body)
    except ValueError as exc:
        raise HTTPException(422, str(exc)) from exc

    if not freecad_available():
        raise HTTPException(
            503,
            "FreeCADCmd is required for Create. Install FreeCAD under vendor/freecad or set FREECADCMD.",
        )

    op = feat["op"]
    combine = feat["combine"]
    label_map = {"box": "Box", "cylinder": "Cylinder", "sphere": "Sphere", "cone": "Cone", "torus": "Torus"}

    if combine != "new":
        # Boolean Create needs a STEP base under FreeCAD; mesh CSG path is retired.
        raise HTTPException(
            501,
            "Boolean Create (add/cut/intersect) is not available yet on the FreeCAD path. "
            "Create a new solid, or use Extrude/Cut on an existing FreeCAD part.",
        )

    dims = {k: feat[k] for k in feat if k not in {"op", "combine", "at"}}
    stem_base = f"xr_{op}" if body.xr else op
    basename = _next_primitive_basename(project_path, stem_base)
    try:
        published = create_primitive_solid(
            project_path=project_path,
            stem=basename,
            op=op,
            at=feat.get("at") or [0.0, 0.0, 0.0],
            extra_meta={"xr": True} if body.xr else None,
            **dims,
        )
    except Exception as exc:
        raise HTTPException(422, str(exc)) from exc

    primary = published.get("primary") or f"{basename}.glb"
    meta = {**body.model_dump(), "engine": "freecad"}
    entry = _record_history(
        project_path,
        "primitive",
        label_map.get(op, op),
        primary,
        meta=meta,
        user=user,
    )
    project_store.touch_project(project_path)
    _notify_project(
        project_id,
        {
            "type": "model.reload",
            "filename": primary,
            "url": f"/api/projects/{project_id}/files/{primary}",
            "by": user["display_name"],
            "by_user_id": user["id"],
            "action": "create_primitive",
            "timeline_entry": entry,
        },
    )
    return {
        "filename": primary,
        "url": f"/api/projects/{project_id}/files/{primary}",
        "timeline_index": entry["index"],
        "meta": meta,
        "program": None,
        "engine": "freecad",
        "step": published.get("step"),
        "action": "create_primitive",
        "message": f"Created {label_map.get(op, op).lower()} with FreeCAD.",
    }


@app.post("/api/projects/{project_id}/extrude-profile")
def extrude_profile(
    project_id: str,
    body: SketchExtrudeRequest,
    user: dict[str, Any] = Depends(get_current_user),
):
    """Extrude or cut a 2D profile with FreeCADCmd — no FeatureProgram / mesh kernel."""
    from backend.services.freecad_engine import apply_freecad_sketch_extrude, freecad_available

    project_path = _require_project(user, project_id)
    if not freecad_available():
        raise HTTPException(
            503,
            "FreeCADCmd is required for Extrude. Install FreeCAD under vendor/freecad or set FREECADCMD.",
        )
    combine = str(body.combine or "new").strip().lower()
    if combine in {"add", "join", "pad"}:
        combine = "join"
    elif combine in {"cut", "pocket"}:
        combine = "cut"
    elif combine != "intersect":
        combine = "new"
    try:
        published = apply_freecad_sketch_extrude(
            project_path=project_path,
            profile=body.profile,
            height_mm=float(body.height_mm),
            combine=combine,
            plane=body.plane or "XY",
            plane_ref=body.plane_ref,
            at=body.at,
            base_filename=body.base_filename,
        )
    except ValueError as exc:
        raise HTTPException(422, str(exc)) from exc
    except Exception as exc:
        raise HTTPException(422, str(exc)) from exc

    primary = published.get("primary") or published.get("glb")
    if not primary:
        raise HTTPException(422, "FreeCAD extrude produced no GLB")
    op_label = "Cut" if combine == "cut" else ("Join" if combine == "join" else "Extrude")
    meta = {**body.model_dump(), "engine": "freecad", "pipeline": "freecad", "combine": combine}
    entry = _record_history(
        project_path,
        "extrude",
        f"FreeCAD {op_label} {abs(float(body.height_mm)):g}mm",
        primary,
        meta={**meta, "step": published.get("step")},
        user=user,
    )
    project_store.touch_project(project_path)
    replace = body.base_filename if published.get("replace") else None
    _notify_project(
        project_id,
        {
            "type": "model.reload",
            "filename": primary,
            "url": f"/api/projects/{project_id}/files/{primary}",
            "by": user["display_name"],
            "by_user_id": user["id"],
            "action": "extrude",
            "pipeline": "freecad",
            "timeline_entry": entry,
        },
    )
    return {
        "filename": primary,
        "url": f"/api/projects/{project_id}/files/{primary}",
        "timeline_index": entry["index"],
        "timeline_entry": entry,
        "meta": meta,
        "parent": replace,
        "replace_catalog": replace,
        "action": "extrude",
        "pipeline": "freecad",
        "engine": "freecad",
        "step": published.get("step"),
        "message": f"{op_label} applied with FreeCAD.",
    }


@app.post("/api/projects/{project_id}/files/{filename:path}/draw-route")
def draw_route_file(
    project_id: str,
    filename: str,
    body: DrawRouteRequest,
    user: dict[str, Any] = Depends(get_current_user),
):
    project_path = _require_project(user, project_id)
    src = project_path / filename
    if not src.is_file():
        raise HTTPException(404, "File not found")
    mesh = cad_service.load_mesh(src)
    try:
        route_type = "loops" if body.route_type in {"loop", "loops", "wire_loops", "clips"} else "duct"
        result = cad_service.add_route_geometry(
            mesh,
            body.points,
            style=route_type,
            radius=cad_service.length_from_mm(mesh, body.diameter_mm / 2.0),
            loop_width=cad_service.length_from_mm(mesh, body.loop_width_mm) if body.loop_width_mm else None,
            loop_height=cad_service.length_from_mm(mesh, body.loop_height_mm) if body.loop_height_mm else None,
            loop_spacing=cad_service.length_from_mm(mesh, body.loop_spacing_mm) if body.loop_spacing_mm else None,
            surface_normals=body.surface_normals,
            surface_locked=body.surface_locked,
        )
    except ValueError as exc:
        raise HTTPException(422, str(exc)) from exc

    suffix = "_loops" if route_type == "loops" else "_duct"
    stem = src.stem.replace("_edited", "").replace("_hole", "").replace("_duct", "").replace("_loops", "") + suffix
    out = project_path / f"{stem}.glb"
    cad_service.export_mesh(result, out)
    meta = {
        "route_type": route_type,
        "point_count": len(body.points),
        "points": body.points[:80],
        "surface_locked": body.surface_locked,
        "surface_normals": body.surface_normals[:80] if body.surface_normals else None,
        "diameter_mm": body.diameter_mm,
        "loop_width_mm": body.loop_width_mm,
        "loop_height_mm": body.loop_height_mm,
        "loop_spacing_mm": body.loop_spacing_mm,
    }
    label = "Wire loops" if route_type == "loops" else "Wire duct"
    entry = _record_history(
        project_path,
        "draw_route",
        f"{label} along path",
        out.name,
        meta=meta,
        user=user,
    )
    _append_mesh_edit(project_path, filename, {"op": "draw_route", "parent": filename, "child": out.name, **meta})
    project_store.touch_project(project_path)
    _notify_project(
        project_id,
        {
            "type": "model.reload",
            "filename": out.name,
            "url": f"/api/projects/{project_id}/files/{out.name}",
            "by": user["display_name"],
            "by_user_id": user["id"],
            "action": "draw_route",
            "timeline_entry": entry,
        },
    )
    return {
        "filename": out.name,
        "url": f"/api/projects/{project_id}/files/{out.name}",
        "timeline_index": entry["index"],
        "meta": meta,
        "parent": filename,
        "action": "draw_route",
        "message": f"Added {label.lower()} along {len(body.points)} path points.",
    }


@app.post("/api/projects/{project_id}/files/{filename:path}/draw-hole")
def draw_hole_file(
    project_id: str,
    filename: str,
    body: DrawHoleRequest,
    user: dict[str, Any] = Depends(get_current_user),
):
    project_path = _require_project(user, project_id)
    src = project_path / filename
    if not src.is_file():
        raise HTTPException(404, "File not found")

    mesh = cad_service.load_mesh(src)
    try:
        if body.placement == "center":
            if body.face_index is None:
                raise ValueError("Pick a face first so Draw can find the face center.")
            position, axis = cad_service.face_region_center_and_normal(mesh, body.face_index)
        else:
            if not body.position:
                raise ValueError("Pick a face or point first so Draw knows where to place the hole.")
            position = body.position
            axis = body.normal or [0, 0, 1]
        diameter = cad_service.length_from_mm(mesh, body.diameter_mm)
        result = cad_service.hole_at_point(
            mesh,
            position,
            axis=axis,
            diameter=diameter,
            through=body.through_all,
        )
    except ValueError as exc:
        raise HTTPException(422, str(exc)) from exc

    stem = src.stem.replace("_edited", "").replace("_hole", "") + "_hole"
    out = project_path / f"{stem}.glb"
    cad_service.export_mesh(result, out)
    meta = {
        "face_index": body.face_index,
        "position": position,
        "normal": axis,
        "diameter_mm": body.diameter_mm,
        "placement": body.placement,
        "through_all": body.through_all,
    }
    entry = _record_history(
        project_path,
        "hole",
        f"Hole {body.diameter_mm:g}mm",
        out.name,
        meta=meta,
        user=user,
    )
    _append_mesh_edit(project_path, filename, {"op": "draw_hole", "parent": filename, "child": out.name, **meta})
    project_store.touch_project(project_path)
    _notify_project(
        project_id,
        {
            "type": "model.reload",
            "filename": out.name,
            "url": f"/api/projects/{project_id}/files/{out.name}",
            "by": user["display_name"],
            "by_user_id": user["id"],
            "action": "draw_hole",
            "timeline_entry": entry,
        },
    )
    return {
        "filename": out.name,
        "url": f"/api/projects/{project_id}/files/{out.name}",
        "timeline_index": entry["index"],
        "meta": meta,
        "parent": filename,
        "action": "draw_hole",
        "message": f"Added a {body.diameter_mm:g} mm through-hole.",
    }


def _edited_output(project_path: Path, src: Path, suffix: str) -> Path:
    base = src.stem
    for tag in ("_edited", "_pulled", "_mirrored", "_body"):
        base = base.replace(tag, "")
    stem = f"{base}{suffix}"
    if (project_path / f"{stem}.glb").exists() and suffix == "_body":
        i = 2
        while (project_path / f"{base}_body{i}.glb").exists():
            i += 1
        stem = f"{base}_body{i}"
    return project_path / f"{stem}.glb"


@app.post("/api/projects/{project_id}/files/{filename:path}/face-pull")
def face_pull_file(
    project_id: str,
    filename: str,
    body: FacePullRequest,
    user: dict[str, Any] = Depends(get_current_user),
):
    """Pad/Pocket / Press-Pull: FreeCAD B-rep when STEP exists; else FeatureProgram; mesh fallback."""
    project_path = _require_project(user, project_id)
    src = project_path / filename
    if not src.is_file():
        raise HTTPException(404, "File not found")

    face_indices = sorted({int(i) for i in (body.face_indices or ([] if body.face_index is None else [body.face_index])) if int(i) >= 0})
    kernel_face_indices = sorted({
        int(i) for i in (body.kernel_face_indices or ([] if body.kernel_face_index is None else [body.kernel_face_index]))
        if int(i) >= 0
    })
    has_kernel_face = bool(kernel_face_indices) or (body.center is not None and body.normal is not None)
    if not face_indices and not has_kernel_face:
        raise HTTPException(400, "Pick one or more faces before applying Press-Pull.")

    # Prefer FreeCAD B-rep Pad/Pocket when a sibling STEP is available (viewport CAD rebuild).
    distance_mm = body.distance_mm if body.distance_mm is not None else float(body.distance)
    distance2_mm = body.distance2_mm if body.distance2_mm is not None else float(body.distance2 or 0.0)
    try:
        from backend.services.freecad_engine import (
            apply_freecad_face_pad,
            freecad_available,
            resolve_project_step,
        )
    except Exception:
        apply_freecad_face_pad = None  # type: ignore
        freecad_available = lambda: False  # type: ignore
        resolve_project_step = None  # type: ignore

    had_step = bool(resolve_project_step and resolve_project_step(project_path, filename))
    freecad_exc: Exception | None = None
    if (
        apply_freecad_face_pad
        and freecad_available()
        and had_step
        and abs(float(body.taper_deg or 0.0)) < 1e-6
    ):
        try:
            fc = apply_freecad_face_pad(
                project_path=project_path,
                filename=filename,
                face_index=face_indices[0] if face_indices else None,
                face_indices=face_indices or None,
                kernel_face_index=kernel_face_indices[0] if kernel_face_indices else None,
                kernel_face_indices=kernel_face_indices or None,
                center=body.center,
                distance_mm=distance_mm,
                op=body.op,
                normal=body.normal,
                through_all=bool(body.through_all),
                direction=body.direction,
                distance2_mm=distance2_mm,
            )
            out_name = fc.get("primary") or fc.get("glb")
            out = project_path / out_name
            op_label = body.op if body.op != "auto" else ("cut" if distance_mm < 0 else "join")
            meta = body.model_dump()
            meta["face_indices"] = face_indices
            meta["pipeline"] = "freecad"
            meta["distance_mm"] = distance_mm
            meta["feature"] = fc.get("feature")
            entry = _record_history(
                project_path,
                "face_pad",
                f"FreeCAD Pad/Pocket {op_label} {abs(distance_mm):g}mm",
                out.name,
                meta={**meta, "step": fc.get("step"), "source": fc.get("source")},
                user=user,
            )
            project_store.touch_project(project_path)
            replace = filename if fc.get("replace", True) else None
            _notify_project(
                project_id,
                {
                    "type": "model.reload",
                    "filename": out.name,
                    "url": f"/api/projects/{project_id}/files/{out.name}",
                    "by": user["display_name"],
                    "by_user_id": user["id"],
                    "action": "face_pad",
                    "pipeline": "freecad",
                    "timeline_entry": entry,
                },
            )
            return {
                "filename": out.name,
                "url": f"/api/projects/{project_id}/files/{out.name}",
                "timeline_index": entry["index"],
                "timeline_entry": entry,
                "meta": meta,
                "parent": filename,
                "replace_catalog": replace,
                "action": "face_pad",
                "pipeline": "freecad",
                "step": fc.get("step"),
                "source": fc.get("source"),
            }
        except Exception as exc:
            freecad_exc = exc
            logger.warning("FreeCAD face pad failed: %s", exc)
            raise HTTPException(422, f"FreeCAD Pad/Pocket failed: {exc}") from exc

    # Prefer parametric kernel when this model has a FeatureProgram (real CAD).
    # Skip AI generation paths — this only edits existing parametric solids.
    prog = _program_file_for(project_path, filename)
    try:
        from backend.services.program_edits import apply_face_pad, can_use_kernel_face_pad
    except Exception:
        apply_face_pad = None  # type: ignore
        can_use_kernel_face_pad = None  # type: ignore

    # Kernel Pad/Pocket always uses millimetres.

    if (
        prog
        and apply_face_pad
        and can_use_kernel_face_pad
        and can_use_kernel_face_pad(
            op=body.op,
            direction=body.direction,
            taper_deg=body.taper_deg,
        )
    ):
        try:
            kernel_result = apply_face_pad(
                project_path,
                prog,
                src,
                face_index=face_indices[0],
                distance=distance_mm,
                op=body.op,
                normal=body.normal,
                through=body.through_all,
            )
            out_name = kernel_result.get("primary") or f"{prog.stem}.glb"
            out = project_path / out_name
            op_label = body.op if body.op != "auto" else ("cut" if distance_mm < 0 else "join")
            meta = body.model_dump()
            meta["face_indices"] = face_indices
            meta["pipeline"] = "kernel"
            meta["distance_mm"] = distance_mm
            meta["feature"] = kernel_result.get("feature")
            entry = _record_history(
                project_path,
                "face_pad",
                f"Kernel Pad/Pocket {op_label} {abs(distance_mm):g}mm (build123d)",
                out.name,
                meta={**meta, "program": kernel_result.get("program")},
                user=user,
            )
            project_store.touch_project(project_path)
            _notify_project(
                project_id,
                {
                    "type": "model.reload",
                    "filename": out.name,
                    "url": f"/api/projects/{project_id}/files/{out.name}",
                    "by": user["display_name"],
                    "by_user_id": user["id"],
                    "action": "face_pad",
                    "pipeline": "kernel",
                    "timeline_entry": entry,
                },
            )
            return {
                "filename": out.name,
                "url": f"/api/projects/{project_id}/files/{out.name}",
                "timeline_index": entry["index"],
                "timeline_entry": entry,
                "meta": meta,
                "parent": filename,
                "replace_catalog": filename,
                "action": "face_pad",
                "pipeline": "kernel",
                "program": kernel_result.get("program"),
            }
        except Exception as exc:
            logger.warning("Kernel face pad failed — falling back to mesh face-pull: %s", exc)

    if had_step and freecad_available():
        detail = str(freecad_exc) if freecad_exc else "FreeCAD Pad/Pocket could not edit this STEP solid."
        raise HTTPException(422, detail)

    operation_src = src
    viewer_name = cad_service.viewer_filename_for_model(src.name, project_path)
    viewer_src = project_path / viewer_name
    # Mesh path: convert mm → model units when distance_mm was provided.
    try:
        probe = cad_service.load_mesh(src)
        dist_model = (
            cad_service.length_from_mm(probe, abs(distance_mm)) * (1.0 if distance_mm >= 0 else -1.0)
            if body.distance_mm is not None
            else float(body.distance)
        )
        dist2_model = (
            cad_service.length_from_mm(probe, abs(distance2_mm))
            if body.distance2_mm is not None
            else float(body.distance2 or 0.0)
        )
    except Exception:
        dist_model = float(body.distance)
        dist2_model = float(body.distance2 or 0.0)
    pull_kwargs = dict(
        distance=dist_model,
        op=body.op,
        direction=body.direction,
        distance2=dist2_model,
        taper_deg=body.taper_deg,
        through=body.through_all,
        normal=body.normal,
        body_index=body.body_index,
        body_name=body.body_name,
    )
    suffix = "_body" if body.op == "new_body" else "_pulled"
    out = _edited_output(project_path, operation_src, suffix)
    try:
        cad_service.face_pull_scene_body(src, face_indices, out_path=out, **pull_kwargs)
    except ValueError as exc:
        message = str(exc)
        if "face_index out of range" not in message or viewer_src == src or not viewer_src.is_file():
            raise HTTPException(422, message) from exc
        try:
            out = _edited_output(project_path, viewer_src, suffix)
            cad_service.face_pull_scene_body(viewer_src, face_indices, out_path=out, **pull_kwargs)
            operation_src = viewer_src
        except ValueError as retry_exc:
            raise HTTPException(422, str(retry_exc)) from retry_exc
    op_label = body.op if body.op != "auto" else ("cut" if distance_mm < 0 else "join")
    meta = body.model_dump()
    meta["face_indices"] = face_indices
    meta["pipeline"] = "mesh"
    meta["distance_mm"] = distance_mm
    entry = _record_history(
        project_path,
        "face_pull",
        f"Press-pull {len(face_indices)} face{'s' if len(face_indices) != 1 else ''} {op_label} {abs(distance_mm):g}mm",
        out.name,
        meta=meta,
        user=user,
    )
    _append_mesh_edit(project_path, operation_src.name, {"op": "face_pull", "parent": operation_src.name, "child": out.name, **meta})
    _append_mesh_edit(project_path, filename, {"op": "face_pull", "parent": filename, "child": out.name, **meta})
    project_store.touch_project(project_path)
    _notify_project(
        project_id,
        {
            "type": "model.reload",
            "filename": out.name,
            "url": f"/api/projects/{project_id}/files/{out.name}",
            "by": user["display_name"],
            "by_user_id": user["id"],
            "action": "face_pull",
            "timeline_entry": entry,
        },
    )
    return {
        "filename": out.name,
        "url": f"/api/projects/{project_id}/files/{out.name}",
        "timeline_index": entry["index"],
        "timeline_entry": entry,
        "meta": meta,
        "parent": filename,
        "replace_catalog": filename,
        "action": "face_pull",
        "pipeline": "mesh",
    }


def _program_file_for(project_path: Path, glb_filename: str) -> "Path | None":
    """Resolve the .program.json that corresponds to a .glb filename."""
    stem = Path(glb_filename).stem
    for suffix in ("_filleted", "_chamfered", "_pulled", "_mirrored", "_body"):
        if stem.endswith(suffix):
            stem = stem[: -len(suffix)]
    candidate = project_path / f"{stem}.program.json"
    if candidate.is_file():
        return candidate
    recovered = _recover_program_from_timeline(project_path, stem)
    if recovered:
        try:
            candidate.write_text(json.dumps(recovered, indent=2), encoding="utf-8")
            return candidate
        except OSError:
            return None
    return None


